<script setup lang="ts">
import { t as uiText } from '@/locales'

import { computed,ref,watch } from 'vue'
import {useResizeObserver} from '@vueuse/core'
import {useRouter} from 'vue-router'
import {phoneCoverageNames,moldReviewTarget,moldReviewActionName} from '@/utils/phoneCoverage'
import {locationNames} from '@/utils/collaboration'
import {phoneMemberName} from '@/utils/phoneMembers'
import type {MarketPhoneCoverage,MarketPhoneMold} from '@/types/marketWatch'
import MasterDataLifecycleDialog from '@/components/MasterDataLifecycleDialog.vue'
import { ElDialog,ElMessage } from 'element-plus'
import FixedTableViewport from '@/components/FixedTableViewport/index.vue'
import * as api from '@/api/modules/phoneReference'
import { useUserStore } from '@/stores/user'
import { useCollaborationWorkspace } from '@/stores/collaborationWorkspace'
import type { CompatiblePhone,PhoneBrand } from '@/types/molds'
import PhoneCodeReview from './PhoneCodeReview.vue'
import PhoneCodeGroups from './PhoneCodeGroups.vue'
import {productionStatusName} from '@/utils/productionStatus'
import PhoneCodeSelector from './PhoneCodeSelector.vue'
import PhoneIdentityIssues from './PhoneIdentityIssues.vue'
import PhoneModelIntake from './PhoneModelIntake.vue'
const props=defineProps<{modelValue:boolean;editable:boolean;keyword?:string;inline?:boolean;initialTab?:string;phoneModelId?:number;coverageOnOpen?:boolean;reviewKind?:import('@/api/modules/code').PhoneModelReviewKind;reviewState?:'pending'|'confirmed'|''}>()
const emit=defineEmits<{ 'update:modelValue':[boolean]; changed:[]; tabChange:[string] }>()
const router=useRouter(),user=useUserStore(),workspace=useCollaborationWorkspace(),tab=ref(props.initialTab||'groups'),keyword=ref(''),page=ref(1),total=ref(0),phones=ref<CompatiblePhone[]>([]),brands=ref<PhoneBrand[]>([]),loading=ref(false),error=ref('')
const active=computed(()=>props.inline||props.modelValue),focusPhoneId=ref(props.phoneModelId),listCanvas=ref<HTMLElement>(),compactRecords=ref(false)
useResizeObserver(listCanvas,entries=>{const width=entries[0]?.contentRect.width;if(width)compactRecords.value=width<650})
const editor=ref(false),busy=ref(false),original=ref<CompatiblePhone|PhoneBrand>(),form=ref({name:'',brandId:undefined as number|undefined,codeItemId:null as number|null,aliases:'',prefixes:[] as {prefix:string;replacement:string}[]}),codeOptions=ref<{codeItemId:number;codeValue:string;codeName:string;status:string;productionStatus?:import('@/types/production').ProductionStatus}[]>([])
const visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)})
let generation=0,coverageGeneration=0
const coverageVisible=ref(false),coveragePhone=ref<CompatiblePhone>(),coverageRows=ref<MarketPhoneCoverage[]>([]),coverageLoading=ref(false),coverageError=ref('')
async function showCoverage(phone:CompatiblePhone){const token=user.token,epoch=++coverageGeneration;coveragePhone.value=phone;coverageRows.value=[];coverageVisible.value=true;coverageLoading.value=true;coverageError.value='';try{const rows=await api.getPhoneModelCoverage(phone.phoneModelId);if(epoch===coverageGeneration&&token===user.token)coverageRows.value=rows}catch{if(epoch===coverageGeneration&&token===user.token)coverageError.value='关联资料读取失败，请重试'}finally{if(epoch===coverageGeneration&&token===user.token)coverageLoading.value=false}}
function goMold(mold:MarketPhoneMold){const target=moldReviewTarget(mold,coveragePhone.value?.phoneModelId);coverageVisible.value=false;visible.value=false;void router.push(target)}
function goApplication(id:number){coverageVisible.value=false;visible.value=false;void router.push({path:'/mold-applications',query:{applicationId:id}})}
async function load() {if(!active.value||['groups','review','issues','intake'].includes(tab.value))return;const gen=++generation,token=user.token;loading.value=true;error.value='';try {const q={page:page.value,size:50,keyword:keyword.value.trim()};if(tab.value==='brands'){const r=await api.getPhoneBrands(q);if(gen===generation&&token===user.token){brands.value=r.content;total.value=r.totalElements}}else if(focusPhoneId.value){const r=await api.getPhoneModelOptions([focusPhoneId.value]);if(gen===generation&&token===user.token){phones.value=r;total.value=r.length;if(!r.length)error.value='指定标准手机不存在或当前账号不可查看，请查询其他手机';if(props.coverageOnOpen&&r[0])void showCoverage(r[0])}}else{const r=await api.getPhoneModels(q);if(gen===generation&&token===user.token){phones.value=r.content;total.value=r.totalElements}}}catch{if(gen===generation&&token===user.token)error.value='资料加载失败，请重试'}finally{if(gen===generation&&token===user.token)loading.value=false}}
function search(){focusPhoneId.value=undefined;page.value=1;void load()}
function issueNavigate(target:{tab:string;keyword:string;kind?:'code_many_names'|'name_many_codes';phoneModelId?:number}){visible.value=false;void router.push({path:'/phone-model-codes',query:{tab:target.tab,keyword:target.keyword,...(target.kind?{kind:target.kind}:{}),...(target.phoneModelId?{phoneModelId:target.phoneModelId}:{})}})}
watch(active,v=>{if(v){keyword.value=props.keyword||'';page.value=1;void load()}},{immediate:true})
watch(tab,v=>{page.value=1;emit('tabChange',v);void load()})
watch(()=>props.initialTab,v=>{if(v&&v!==tab.value)tab.value=v})
watch(()=>props.keyword,v=>{keyword.value=v||'';page.value=1;void load()})
watch(()=>props.phoneModelId,v=>{focusPhoneId.value=v;page.value=1;void load()})
watch(()=>user.token,()=>{generation++;coverageGeneration++;coverageVisible.value=false;coverageRows.value=[];phones.value=[];brands.value=[];editor.value=false;detailRow.value=undefined;lifeRow.value=undefined;visible.value=false})
async function open(row?:CompatiblePhone|PhoneBrand) {error.value='';original.value=row;form.value={name:row?('modelName'in row?row.modelName:row.name):'',brandId:row&&'modelName'in row?row.brandId:undefined,codeItemId:row&&'modelName'in row?row.codeItemId:null,aliases:row?(row.aliases||[]).join('\n'):'',prefixes:row&&'name'in row?(row.prefixes||[]).map(p=>({...p})):[]};codeOptions.value=row&&'codeItemId'in row&&row.codeItemId?[{codeItemId:row.codeItemId,codeValue:row.phoneModelCode||'',codeName:row.originalCodeName||row.modelName,status:row.codeStatus||'enabled',productionStatus:row.productionStatus}]:[];editor.value=true;if(tab.value==='phones'){const token=user.token;const r=await api.getPhoneBrands({page:1,size:100,status:'enabled'});if(token===user.token){brands.value=r.content;if(row&&'modelName'in row&&!brands.value.some(b=>b.brandId===row.brandId))brands.value.push({id:row.brandId,brandId:row.brandId,name:row.brandName,status:row.brandStatus||'unknown'})}}}
async function save() {if(!form.value.name.trim())return;const token=user.token;busy.value=true;try {if(tab.value==='brands'){const r=original.value as PhoneBrand|undefined;if(r){const result=await api.savePhoneBrand(r.brandId,{changes:{name:form.value.name.trim(),aliases:form.value.aliases.split('\n').map(s=>s.trim()).filter(Boolean),prefixes:form.value.prefixes.map(p=>({prefix:p.prefix.trim(),replacement:p.replacement.trim()})).filter(p=>p.prefix)},original:{name:r.name,aliases:r.aliases||[],prefixes:r.prefixes||[]}});if(result.status!=='saved')throw new Error('资料已被其他人员修改，请刷新后逐项核对原值')}else await api.createPhoneBrand(form.value.name.trim(),form.value.aliases.split('\n').map(s=>s.trim()).filter(Boolean),form.value.prefixes.map(p=>({prefix:p.prefix.trim(),replacement:p.replacement.trim()})).filter(p=>p.prefix))}else{if(!form.value.brandId){ElMessage.warning(uiText('请指定品牌'));return}const input={brandId:form.value.brandId,modelName:form.value.name.trim(),aliases:form.value.aliases.split('\n').map(s=>s.trim()).filter(Boolean),codeItemId:form.value.codeItemId};const r=original.value as CompatiblePhone|undefined;if(r){const changes:Record<string,unknown>={},before:Record<string,unknown>={};for(const key of ['brandId','modelName','aliases','codeItemId'] as const){if(JSON.stringify(r[key])!==JSON.stringify(input[key])){changes[key]=input[key];before[key]=r[key]}}if(Object.keys(changes).length){const result=await api.savePhoneModel(r.phoneModelId,{changes,original:before});if(result.status!=='saved')throw new Error('资料已被其他人员修改，请刷新后逐项核对原值')}}else await api.createPhoneModel(input)}if(token===user.token){workspace.changed();editor.value=false;await load();emit('changed');ElMessage.success(uiText('基础资料已保存；历史快照不改写'))}}catch(e){if(token===user.token)error.value=e instanceof Error?e.message:'保存失败，请重试'}finally{busy.value=false}}
const detailRow=ref<CompatiblePhone|PhoneBrand>(),lifeRow=ref<CompatiblePhone|PhoneBrand>(),lifeAction=ref<'delete'|'deactivate'|'activate'>('delete')
const referenceKind=computed(()=>'modelName'in (lifeRow.value||{})?'phone-models':'brands')
const referenceRecord=computed(()=>{const r=lifeRow.value;return r?{id:'modelName'in r?r.phoneModelId:r.brandId,name:'modelName'in r?r.modelName:r.name,code:'modelName'in r?r.phoneModelCode||undefined:undefined}:undefined})
function inspectReference(id:number|string){return api.inspectPhoneReference(referenceKind.value,id)}
function actReference(id:number|string,action:'delete'|'deactivate'|'activate',payload:{version:number;requestId:string;reason:string}){return api.phoneReferenceAction(referenceKind.value,id,action,payload)}
function toggle(row:CompatiblePhone|PhoneBrand){lifeRow.value=row;lifeAction.value=row.status==='enabled'?'deactivate':'activate'}
function remove(row:CompatiblePhone|PhoneBrand){lifeRow.value=row;lifeAction.value='delete'}
async function lifecycleCompleted(){lifeRow.value=undefined;detailRow.value=undefined;workspace.changed();await load();emit('changed')}

</script>
<template>
  <component :is="inline?'section':ElDialog" v-bind="inline?{}:{modelValue:visible,title:'手机型号与品牌资料',width:'min(1080px,96vw)',top:'5vh',style:{height:'90dvh'},closeOnClickModal:false}" @update:model-value="visible=$event" class="reference-manager" :class="{'reference-manager--inline':inline}">
    <p v-if="!['issues','intake'].includes(tab)" class="hint">{{tab==='groups'?uiText('停产指我们停产配套产品，仅提醒不禁选；组合型号不自动拆分。'):uiText('编码注册表继续沿用。多个手机可以引用同一编码，也可以不同编码共用一套模具；这里不新建实物或自动分配编码。')}}</p>
    <el-tabs v-model="tab"><el-tab-pane name="groups" :label='uiText("型号编码组")'/><el-tab-pane name="phones" :label='uiText("标准手机成员")'/><el-tab-pane name="intake" :label='uiText("待补手机型号")'/><el-tab-pane name="brands" :label='uiText("品牌")'/><el-tab-pane name="review" :label='uiText("历史关系核对")'/><el-tab-pane name="issues" :label='uiText("资料问题／集中处理")'/></el-tabs>
    <PhoneCodeGroups v-if="tab==='groups'" :visible="active" :editable="editable" :keyword="keyword" @changed="emit('changed')"/>
    <PhoneCodeReview v-else-if="tab==='review'" :keyword="keyword" :initial-kind="reviewKind" :initial-review-state="reviewState" @navigate="visible=false"/>
    <PhoneIdentityIssues v-else-if="tab==='issues'" :visible="active" :keyword="keyword" @changed="emit('changed')" @navigate="issueNavigate"/>
    <PhoneModelIntake v-else-if="tab==='intake'" :visible="active" :editable="editable" :keyword="keyword" @changed="emit('changed')"/>
    <section v-else ref="listCanvas" class="reference-list">
    <div class="reference-tools"><el-input v-model="keyword" :placeholder='uiText("搜索品牌 / 手机名称 / 四位编码")' clearable @keyup.enter="search"/><el-button @click="search">{{ uiText("查询") }}</el-button><el-button v-if="editable" type="primary" @click="open()">{{tab==='brands'?uiText('新增品牌'):uiText('新增手机成员')}}</el-button></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false"/>
    <FixedTableViewport fill :refresh-key="tab==='phones'?phones:brands" v-slot="{tableHeight}">
    <div v-if="compactRecords" class="reference-cards" v-loading="loading" :aria-label="tab==='phones'?uiText('标准手机成员记录'):uiText('品牌记录')">
      <article v-for="row in tab==='phones'?phones:brands" :key="'phoneModelId'in row?row.phoneModelId:row.brandId"><template v-if="'modelName'in row"><strong>{{row.brandName}} · {{row.modelName}}</strong><span>{{ uiText("手机编码 ") }}{{row.phoneModelCode||uiText('待分配')}} · {{row.status==='enabled'?uiText('启用'):uiText('停用')}} · {{productionStatusName(row.productionStatus)}}</span><div><el-button link @click="showCoverage(row)">{{ uiText("查看产品／模具") }}</el-button><el-button link @click="detailRow=row">{{ uiText("详情") }}</el-button><el-button v-if="editable" link @click="open(row)">{{ uiText("编辑") }}</el-button><el-button v-if="editable" link type="danger" @click="remove(row)">{{ uiText("删除") }}</el-button><el-button v-if="editable" link @click="toggle(row)">{{row.status==='enabled'?uiText('停用'):uiText('启用')}}</el-button></div></template><template v-else><strong>{{row.name}}</strong><span>{{ uiText("别名 ") }}{{row.aliases?.join(' / ')||'—'}} · {{row.status==='enabled'?uiText('启用'):uiText('停用')}}</span><div v-if="editable"><el-button link @click="detailRow=row">{{ uiText("详情") }}</el-button><el-button link @click="open(row)">{{ uiText("编辑") }}</el-button><el-button link type="danger" @click="remove(row)">{{ uiText("删除") }}</el-button><el-button link @click="toggle(row)">{{row.status==='enabled'?uiText('停用'):uiText('启用')}}</el-button></div></template></article>
      <el-empty v-if="!(tab==='phones'?phones:brands).length&&!loading" :description='uiText("没有符合条件的资料")' :image-size="60"/>
    </div>
    <el-table v-else-if="tab==='phones'" :data="phones" v-loading="loading" :height="tableHeight"><el-table-column prop="brandName" :label='uiText("品牌")'/><el-table-column prop="modelName" :label='uiText("手机型号")' min-width="260"/><el-table-column :label='uiText("原型号编码")'><template #default="{row}">{{row.phoneModelCode||uiText('待分配')}}</template></el-table-column><el-table-column :label='uiText("资料 / 生产")'><template #default="{row}">{{row.status==='enabled'?uiText('启用'):uiText('停用')}}<small>{{productionStatusName(row.productionStatus)}}</small></template></el-table-column><el-table-column :label='uiText("操作")'><template #default="{row}"><el-button link @click="showCoverage(row)">{{ uiText("查看产品／模具") }}</el-button><el-button link @click="detailRow=row">{{ uiText("详情") }}</el-button><el-button v-if="editable" link @click="open(row)">{{ uiText("编辑") }}</el-button><el-button v-if="editable" link type="danger" @click="remove(row)">{{ uiText("删除") }}</el-button><el-button v-if="editable" link @click="toggle(row)">{{row.status==='enabled'?uiText('停用'):uiText('启用')}}</el-button></template></el-table-column></el-table>
    <el-table v-else :data="brands" v-loading="loading" :height="tableHeight"><el-table-column prop="name" :label='uiText("品牌名称")'/><el-table-column :label='uiText("别名")'><template #default="{row}">{{(row.aliases||[]).join(' / ')||'—'}}</template></el-table-column><el-table-column :label='uiText("状态")'><template #default="{row}">{{row.status==='enabled'?uiText('启用'):uiText('停用')}}</template></el-table-column><el-table-column :label='uiText("操作")' v-if="editable"><template #default="{row}"><el-button link @click="detailRow=row">{{ uiText("详情") }}</el-button><el-button link @click="open(row)">{{ uiText("编辑") }}</el-button><el-button link type="danger" @click="remove(row)">{{ uiText("删除") }}</el-button><el-button link @click="toggle(row)">{{row.status==='enabled'?uiText('停用'):uiText('启用')}}</el-button></template></el-table-column></el-table>
    </FixedTableViewport>
    <el-pagination v-model:current-page="page" :page-size="50" :total="total" layout="total,prev,pager,next" @current-change="load"/>
    </section>
    <el-drawer v-model="coverageVisible" append-to-body :title='uiText("手机关联产品与模具")' size="min(760px,96vw)"><section v-loading="coverageLoading" class="phone-coverage"><h3>{{coveragePhone?phoneMemberName(coveragePhone):uiText('手机待关联')}}</h3><p>{{ uiText("手机编码 ") }}{{coveragePhone?.phoneModelCode||uiText('待分配')}}</p><el-alert v-if="coverageError" :title="coverageError" type="error" :closable="false"><el-button link @click="coveragePhone&&showCoverage(coveragePhone)">{{ uiText("重试") }}</el-button></el-alert><article v-for="c in coverageRows" :key="c.productLineId||c.productLineName"><h4>{{c.productLineName}} · {{phoneCoverageNames[c.state]}}</h4><div v-for="a in c.applications" :key="a.applicationId"><el-button link @click="goApplication(a.applicationId)">{{ uiText("查看申请") }}</el-button><span>{{a.model}} · {{a.tipo||uiText('产品待完善')}}</span></div><div v-for="m in c.molds" :key="m.moldSetId||`archive:${m.itemId}`"><strong>{{m.moldName||m.styleName}}{{ uiText(" · 原刻码 ") }}{{m.engravedCode||uiText('待核对')}}</strong><p>{{m.physicalCode||uiText('适用实物套待核对')}}<span v-if="m.setNo">{{ uiText(" · 第 ") }}{{m.setNo}}{{ uiText(" 套") }}</span> · {{phoneCoverageNames[m.state]}}</p><p>PC {{m.pcCode||uiText('编码待核对')}} · {{m.pcConfirmed?uiText('适配已确认'):uiText('适配待核对')}} ／ TPU {{m.tpuCode||uiText('编码待核对')}} · {{m.tpuConfirmed?uiText('适配已确认'):uiText('适配待核对')}}</p><p v-for="issue in m.reviewReasons" :key="issue.code" class="review-reason">{{issue.message}}</p><p>{{ uiText("PC 位置 ") }}{{locationNames[m.pcLocation||'unknown']||m.pcLocation}} {{m.pcLocationDetail}}{{ uiText(" ／ TPU 位置 ") }}{{locationNames[m.tpuLocation||'unknown']||m.tpuLocation}} {{m.tpuLocationDetail}}</p><p v-if="m.pcEvidence||m.tpuEvidence||m.evidence">{{ uiText("适配依据：PC ") }}{{m.pcEvidence||m.evidence||uiText('待核对')}} ／ TPU {{m.tpuEvidence||m.evidence||uiText('待核对')}}</p><el-button link @click="goMold(m)">{{moldReviewActionName(m,editable)}}</el-button></div></article><p v-if="!coverageRows.length&&!coverageLoading&&!coverageError">{{ uiText("暂无明确关联的产品或模具。已有资料可在模具详情核对兼容手机及适用套。") }}</p></section></el-drawer>
    <el-drawer :model-value="!!detailRow" append-to-body :title='uiText("基础资料详情")' size="min(640px,94vw)" @close="detailRow=undefined"><template v-if="detailRow"><h3>{{'modelName'in detailRow?detailRow.modelName:detailRow.name}}</h3><p v-if="'modelName'in detailRow">{{ uiText("品牌 ") }}{{detailRow.brandName}}{{ uiText(" · 原手机编码 ") }}{{detailRow.phoneModelCode||uiText('待分配')}}</p><p>{{ uiText("别名 ") }}{{detailRow.aliases?.join(' / ')||'—'}}</p><p>{{ uiText("状态 ") }}{{detailRow.status==='enabled'?uiText('启用'):uiText('停用')}}</p><div v-if="editable"><el-button @click="open(detailRow)">{{ uiText("编辑") }}</el-button><el-button @click="toggle(detailRow)">{{detailRow.status==='enabled'?uiText('停用'):uiText('启用')}}</el-button><el-button type="danger" plain @click="remove(detailRow)">{{ uiText("删除") }}</el-button></div></template></el-drawer>
    <MasterDataLifecycleDialog v-if="lifeRow" :record="referenceRecord" :kind-label="referenceKind==='brands'?'手机品牌':'标准手机成员'" :action="lifeAction" :editable="editable" :context="`${referenceKind}:${referenceRecord?.id}`" :load="inspectReference" :perform="actReference" @close="lifeRow=undefined" @completed="lifecycleCompleted" @open="router.push($event)"/>
    <el-dialog v-model="editor" append-to-body :title="uiText('{value0}{value1}',{value0:(original?'编辑':'新增'),value1:(tab==='brands'?'品牌':'手机成员')})" width="min(680px,94vw)" :close-on-click-modal="false"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-form label-position="top"><el-form-item v-if="tab==='phones'" :label='uiText("品牌")'><el-select v-model="form.brandId" filterable><el-option v-for="b in brands" :key="b.brandId" :value="b.brandId" :label="b.name" :disabled="b.status!=='enabled'"/></el-select></el-form-item><el-form-item :label='uiText("名称")'><el-input v-model="form.name" maxlength="255"/></el-form-item><template v-if="tab==='phones'"><el-form-item :label='uiText("已有编码（可留空，待分配）")'><PhoneCodeSelector v-model="form.codeItemId" :members="codeOptions" :brand-id="form.brandId" :disabled="!form.brandId || !!(original&&'codeItemId'in original&&original.codeItemId)" :aria-label='uiText("已有手机编码")'/></el-form-item></template><el-form-item :label="tab==='brands'?uiText('品牌别名（每行一个）'):uiText('型号别名（每行一个）')"><el-input v-model="form.aliases" type="textarea" :rows="3"/></el-form-item><el-form-item v-if="tab==='brands'" :label='uiText("型号前缀转换")'><div class="prefixes"><div v-for="(prefix,index) in form.prefixes" :key="index" class="prefix-row"><el-input v-model="prefix.prefix" :aria-label='uiText("原型号前缀")' :placeholder='uiText("例如 IP")'/><span>→</span><el-input v-model="prefix.replacement" :aria-label='uiText("标准系列前缀")' :placeholder='uiText("例如 iPhone；可留空")'/><el-button size="small" @click="form.prefixes.splice(index,1)">{{ uiText("删除") }}</el-button></div><el-button size="small" @click="form.prefixes.push({prefix:'',replacement:''})">{{ uiText("添加前缀") }}</el-button><p class="hint">{{ uiText("仅转换明确前缀；保留代数、Pro、Max、4G／5G、地区及孔型。IP → iPhone；Galaxy 的替换可留空。") }}</p></div></el-form-item></el-form><template #footer><el-button @click="editor=false">{{ uiText("取消") }}</el-button><el-button type="primary" :loading="busy" @click="save">{{ uiText("保存资料") }}</el-button></template></el-dialog>
  </component>
</template>
<style>.reference-manager.el-dialog{display:flex;flex-direction:column}.reference-manager>.el-dialog__body{flex:1;min-height:0;display:flex;flex-direction:column;gap:8px;overflow:hidden}.reference-manager>.el-dialog__body>.hint{margin:0;flex:none}.reference-manager>.el-dialog__body>.el-tabs{flex:none}.reference-manager>.el-dialog__body>.reference-tools{flex:none}</style>
